#!/usr/bin/env python3
"""Evaluate release snapshots and emit desk receipts."""

import json
import math
import sys


EVENT_TYPES = {"candidate", "test", "approval", "revoke"}
RECEIPT_KEYS = (
    "case_id", "status", "build", "next_action", "reason",
    "action_performed",
)


class InputError(ValueError):
    pass


def _text(value, where, allow_empty=False):
    if not isinstance(value, str) or (not allow_empty and value == ""):
        raise InputError(f"{where} must be a non-empty string")


def validate_cases(data):
    if not isinstance(data, list):
        raise InputError("top-level input must be a JSON array")
    for index, case in enumerate(data):
        where = f"case[{index}]"
        if not isinstance(case, dict):
            raise InputError(f"{where} must be an object")
        for key in ("case_id", "release", "events"):
            if key not in case:
                raise InputError(f"{where} is missing {key}")
        _text(case["case_id"], f"{where}.case_id")
        _text(case["release"], f"{where}.release")
        if case.get("owner") is not None:
            _text(case["owner"], f"{where}.owner", allow_empty=True)
        if not isinstance(case["events"], list):
            raise InputError(f"{where}.events must be an array")
        for event_index, event in enumerate(case["events"]):
            ew = f"{where}.events[{event_index}]"
            if not isinstance(event, dict):
                raise InputError(f"{ew} must be an object")
            if "release" not in event:
                raise InputError(f"{ew} is missing release")
            _text(event["release"], f"{ew}.release")
            # Records for another release do not participate in this desk
            # decision; do not let their unrelated vocabulary block it.
            if event["release"] != case["release"]:
                continue
            for key in ("id", "seq", "type"):
                if key not in event:
                    raise InputError(f"{ew} is missing {key}")
            _text(event["id"], f"{ew}.id")
            seq = event["seq"]
            if (not isinstance(seq, (int, float)) or isinstance(seq, bool)
                    or not math.isfinite(seq)):
                raise InputError(f"{ew}.seq must be a finite number")
            event_type = event["type"]
            if event_type not in EVENT_TYPES:
                raise InputError(f"{ew}.type is unknown")
            if event_type in {"candidate", "test", "approval", "revoke"}:
                if "build" not in event:
                    raise InputError(f"{ew} is missing build")
                _text(event["build"], f"{ew}.build")
            if event_type == "test":
                if event.get("outcome") not in {"pass", "fail"}:
                    raise InputError(f"{ew}.outcome must be pass or fail")
            if event_type in {"approval", "revoke"}:
                if "actor" not in event:
                    raise InputError(f"{ew} is missing actor")
                _text(event["actor"], f"{ew}.actor")


def _receipt(case_id, status, build, next_action, reason):
    return dict(zip(RECEIPT_KEYS, (
        case_id, status, build, next_action, reason, False,
    )))


def evaluate_case(case):
    """Evaluate one already-validated case."""
    case_id = case["case_id"]
    owner = case.get("owner")
    if owner is None or owner == "":
        return _receipt(case_id, "needs_input", None, "request_input",
                        "missing_owner")

    events = [e for e in case["events"] if e["release"] == case["release"]]

    by_id = {}
    for event in events:
        prior = by_id.get(event["id"])
        if prior is None:
            by_id[event["id"]] = event
        elif prior != event:
            return _receipt(case_id, "needs_review", None, "review",
                            "conflicting_event")
    events = list(by_id.values())

    by_seq = {}
    for event in events:
        prior = by_seq.get(event["seq"])
        if prior is not None and prior != event:
            return _receipt(case_id, "needs_review", None, "review",
                            "ambiguous_order")
        by_seq[event["seq"]] = event
    events.sort(key=lambda event: event["seq"])

    candidates = [e for e in events if e["type"] == "candidate"]
    if not candidates:
        return _receipt(case_id, "needs_input", None, "request_input",
                        "missing_candidate")
    candidate = candidates[-1]
    build = candidate["build"]

    active = [e for e in events
              if e["seq"] > candidate["seq"] and e.get("build") == build]
    tests = [e for e in active if e["type"] == "test"]
    if not tests:
        return _receipt(case_id, "needs_input", build, "request_input",
                        "missing_test")
    latest_test = tests[-1]
    if latest_test["outcome"] == "fail":
        return _receipt(case_id, "needs_review", build, "review",
                        "tests_failed")

    approved = False
    for event in active:
        if event["seq"] <= latest_test["seq"] or event.get("actor") != owner:
            continue
        if event["type"] == "approval":
            approved = True
        elif event["type"] == "revoke":
            approved = False
    if not approved:
        return _receipt(case_id, "needs_approval", build,
                        "request_approval", "owner_approval_missing")
    return _receipt(case_id, "completed", build, "ready", "ready")


def evaluate_cases(data):
    validate_cases(data)
    return [evaluate_case(case) for case in data]


def _reject_constant(value):
    raise InputError(f"invalid JSON number {value}")


def main(argv):
    if len(argv) != 3:
        print(f"usage: {argv[0]} INPUT.json OUTPUT.json", file=sys.stderr)
        return 2
    input_path, output_path = argv[1:]
    try:
        with open(input_path, "r", encoding="utf-8") as source:
            data = json.load(source, parse_constant=_reject_constant)
        # The invocation contract supplies one case and expects one receipt.
        # Retain array support for convenient local batch checks, preserving
        # the input's top-level shape in the output.
        if isinstance(data, dict):
            result = evaluate_cases([data])[0]
        elif isinstance(data, list):
            result = evaluate_cases(data)
        else:
            raise InputError("top-level input must be a JSON object or array")
        # Evaluation finishes before the output file is touched.
        with open(output_path, "w", encoding="utf-8") as destination:
            json.dump(result, destination, indent=2, ensure_ascii=False)
            destination.write("\n")
    except (InputError, json.JSONDecodeError, OSError) as exc:
        print(f"release_desk: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
